private static volatile @Nullable RemoteConnector remoteConnector;

@FunctionalInterface
public interface RemoteConnector {
   ChannelFuture connect(
      InetSocketAddress address,

Connection connection, ChannelInitializer<Channel> initializer
      );
   }

   public static void setRemoteConnector(@Nullable RemoteConnector connector) {
      remoteConnector = connector;
   }

public boolean isLocalTransport() {
   return this.isMemoryConnection() || this.address instanceof LocalAddress;
}
